using namespace std;

class Solution {
public:
    int minLengthAfterRemovals(string s) {
        vector<char> stack;
        for (char c : s) {
            if (!stack.empty() && stack.back() != c) {
                stack.pop_back();
            } else {
                stack.push_back(c);
            }
        }
        return stack.size();
    }
};

import java.util.*;

class Solution {
    public int minLengthAfterRemovals(String s) {
        StringBuilder stack = new StringBuilder();
        for (char c : s.toCharArray()) {
            int len = stack.length();
            if (len > 0 && stack.charAt(len - 1) != c) {
                stack.deleteCharAt(len - 1);
            } else {
                stack.append(c);
            }
        }
        return stack.length();
    }
}

var minLengthAfterRemovals = function(s) {
    const stack = [];
    for (const c of s) {
        if (stack.length > 0 && stack[stack.length - 1] !== c) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }
    return stack.length;
};
